ALTER TABLE "topics" ADD CONSTRAINT "topics_seo_keywords_check" CHECK (jsonb_typeof("topics"."seo_keywords") = 'array' and jsonb_array_length("topics"."seo_keywords") <= 8 and ("topics"."content_type" = 'expert_article' or "topics"."seo_keywords" = '[]'::jsonb));